1|// Bounded stack of played track ids for Previous. Pure: the reader owns
2|// the array, these helpers push and pop it. Automatic switches and Next
3|// push the outgoing id; Previous pops without pushing back.
4|export const HISTORY_LIMIT = 50;
5|
6|export function pushHistory(hist: readonly string[], id: string | null): string[] {
7|  if (id === null) return [...hist];
8|  const next = [...hist, id];
9|  return next.length > HISTORY_LIMIT ? next.slice(next.length - HISTORY_LIMIT) : next;
10|}
11|
12|export function popHistory(hist: readonly string[]): { hist: string[]; id: string } | null {
13|  if (hist.length === 0) return null;
14|  return { hist: hist.slice(0, -1), id: hist[hist.length - 1] as string };
15|}

Read text file `core/music-credit.ts`.
1|// Now-playing line: display title · composer · source. displayTitle
2|// strips nicknames, key, and opus/catalogue suffixes from the manifest
3|// title; the tooltip keeps the full title. Source is the artist plus
4|// the platform named in the attribution (Musopen, Jamendo) when the
5|// artist does not already name it.
6|import type { Track } from "./music-types";
7|
8|export interface NowPlaying {
9|  line: string;
10|  full: string;
11|}
12|
13|type Credit = { title: string } & {
14|  [K in "composer" | "artist" | "license" | "attribution"]?: Pick<Track, K>[K] | null;
15|};
16|
17|export function displayTitle(title: string): string {
18|  const out = title
19|    .replace(/\s*"[^"]*"/g, "")
20|    .replace(/\s+in\s+[A-G](?:-flat|-sharp)?\s+(?:major|minor)\b/gi, "")
21|    .replace(/\s*,?\s*\b(?:Op\.\s*\d+|BWV\s*\d*|K\.\s*\d+).*$/, "");
22|  return out
23|    .replace(/\s{2,}/g, " ")
24|    .replace(/\s+,/g, ",")
25|    .replace(/^[,\s]+|[,\s]+$/g, "");
26|}
27|
28|function creditSource(artist: string | null | undefined, attribution: string | null | undefined): string | null {
29|  if (!artist) return null;
30|  const platform = /musopen/i.test(attribution ?? "")
31|    ? "Musopen"
32|    : /jamendo/i.test(attribution ?? "")
33|      ? "Jamendo"
34|      : null;
35|  if (platform && !artist.toLowerCase().includes(platform.toLowerCase())) {
36|    return `${artist} / ${platform}`;
37|  }
38|  return artist;
39|}
40|
41|export function nowPlaying(track: Credit | null): NowPlaying | null {
42|  if (track === null) return null;
43|  const who = track.composer ?? null;
44|  const rawSource = creditSource(track.artist, track.attribution);
45|  const source = rawSource && rawSource !== who ? rawSource : null;
46|  const line = [displayTitle(track.title), who, source].filter((p): p is string => p !== null).join(" · ");
47|  const full = [track.title, who, source, track.license ?? null, track.attribution ?? null]
48|    .filter((p): p is string => p !== null)
49|    .join(" · ");
50|  return { line, full };
51|}

