1|// Pure music scheduler. The reader calls it with explicit nowSec values,
2|// so dwell, hysteresis, and hard cuts are testable without timers.
3|import {
4|  MUSIC_CONFIG,
5|  candidatesFor,
6|  nextTrack,
7|  pickRandomTrack,
8|  requestStyleChange,
9|  rankTracks,
10|  resolveConfig,
11|  scoreTrack,
12|} from "./music";
13|import type { MusicConfig, MusicManifest, SceneSignal, SelectEnv, Track } from "./music";
14|
15|export interface SchedulerState {
16|  currentId: string | null;
17|  currentStartedSec: number;
18|  activeSceneId: string | null;
19|  pendingSceneId: string | null;
20|  pendingSinceSec: number;
21|  overrideId: string | null;
22|  overrideSceneId: string | null;
23|  playlist: { id: string; index: number } | null;
24|}
25|
26|export interface ScheduleDecision {
27|  state: SchedulerState;
28|  switchToId: string | null;
29|  crossfadeSec: number;
30|  hardCut: boolean;
31|}
32|
33|export function initScheduler(): SchedulerState {
34|  return {
35|    currentId: null,
36|    currentStartedSec: 0,
37|    activeSceneId: null,
38|    pendingSceneId: null,
39|    pendingSinceSec: 0,
40|    overrideId: null,
41|    overrideSceneId: null,
42|    playlist: null,
43|  };
44|}
45|
46|function noChange(state: SchedulerState): ScheduleDecision {
47|  return { state, switchToId: null, crossfadeSec: 0, hardCut: false };
48|}
49|
50|function topRanked(
51|  signal: SceneSignal | null,
52|  manifest: MusicManifest,
53|  config: MusicConfig,
54|  excludeId?: string | null,
55|): { id: string; score: number } | null {
56|  if (signal === null) {
57|    const ids = [...manifest.tracks]
58|      .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
59|      .filter((t) => t.id !== excludeId);
60|    const first = ids[0];
61|    return first ? { id: first.id, score: 0 } : null;
62|  }
63|  const ranked = rankTracks(signal, manifest, config).filter((t) => t.id !== excludeId);
64|  const best = ranked[0];
65|  return best ? { id: best.id, score: scoreTrack(signal, best, config) } : null;
66|}
67|
68|// Scheduled select: the draw keeps the current
69|// track when it is eligible, so rescans do not churn. Dwell is handled
70|// by promotion; min-track holds the current pick.
71|function evaluateRandom(
72|  state: SchedulerState,
73|  signal: SceneSignal,
74|  styleTracks: Track[],
75|  scoped: MusicManifest,
76|  nowSec: number,
77|  config: MusicConfig,
78|  env: SelectEnv,
79|): ScheduleDecision {
80|  const pick = pickRandomTrack(styleTracks, signal, state.currentId, env.rng, config);
81|  if (!pick || pick.id === state.currentId) return noChange(state);
82|  if (state.currentId !== null && nowSec - state.currentStartedSec < config.minTrackSec) {
83|    return noChange(state);
84|  }
85|  return {
86|    state: { ...state, currentId: pick.id, currentStartedSec: nowSec },
87|    switchToId: pick.id,
88|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
89|    hardCut: false,
90|  };
91|}
92|
93|function evaluateSwitch(
94|  state: SchedulerState,
95|  signal: SceneSignal | null,
96|  manifest: MusicManifest,
97|  nowSec: number,
98|  config: MusicConfig,
99|  env: SelectEnv,
100|): ScheduleDecision {
101|  if (signal === null) return noChange(state);
102|  if (state.playlist !== null) return noChange(state);
103|  const styleTracks = candidatesFor(env.selection, manifest);
104|  if (styleTracks.length === 0) return noChange(state);
105|  const scoped = { ...manifest, tracks: styleTracks };
106|  return evaluateRandom(state, signal, styleTracks, scoped, nowSec, config, env);
107|}
108|
109|function promote(
110|  state: SchedulerState,
111|  sceneId: string,
112|  signal: SceneSignal | null,
113|  manifest: MusicManifest,
114|  nowSec: number,
115|  config: MusicConfig,
116|  env: SelectEnv,
117|): ScheduleDecision {
118|  const settled: SchedulerState = {
119|    ...state,
120|    activeSceneId: sceneId,
121|    pendingSceneId: null,
122|    pendingSinceSec: 0,
123|    overrideId: null,
124|    overrideSceneId: null,
125|  };
126|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
127|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
128|}
129|
130|// The reading position entered a scene. It becomes pending and the dwell
131|// clock restarts, so fast scrolling keeps only the newest scene. After
132|// the pending scene holds for dwellSec it becomes active. The first
133|// track ever plays at once, with no dwell.
134|export function observeScene(
135|  state: SchedulerState,
136|  sceneId: string,
137|  signal: SceneSignal | null,
138|  manifest: MusicManifest,
139|  nowSec: number,
140|  env: SelectEnv,
141|  override?: Partial<MusicConfig>,
142|): ScheduleDecision {
143|  const config = resolveConfig(override ?? MUSIC_CONFIG);
144|  if (state.currentId === null) {
145|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
146|  }
147|  if (sceneId === state.activeSceneId) {
148|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
149|  }
150|  if (sceneId !== state.pendingSceneId) {
151|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
152|  }
153|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
154|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
155|}
156|
157|// Time passed: settle a pending scene whose dwell has expired, or
158|// re-check the active scene (a hold from minTrackSec may have expired).
159|// The reader passes the pending signal when one exists, else the active.
160|export function tickScheduler(
161|  state: SchedulerState,
162|  signal: SceneSignal | null,
163|  manifest: MusicManifest,
164|  nowSec: number,
165|  env: SelectEnv,
166|  override?: Partial<MusicConfig>,
167|): ScheduleDecision {
168|  const config = resolveConfig(override ?? MUSIC_CONFIG);
169|  if (state.currentId === null) return noChange(state);
170|  if (state.pendingSceneId !== null) {
171|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
172|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config, env);
173|  }
174|  // A skip override holds until the next scene change; promotion clears it.
175|  if (state.overrideId !== null) return noChange(state);
176|  if (state.activeSceneId === null) return noChange(state);
177|  return evaluateSwitch(state, signal, manifest, nowSec, config, env);
178|}
179|
180|// Reader skip: the same-emotion Next rule, applied at once with the
181|// normal crossfade. The choice holds until the next scene change.
182|export function requestNext(
183|  state: SchedulerState,
184|  signal: SceneSignal | null,
185|  manifest: MusicManifest,
186|  nowSec: number,
187|  env: SelectEnv,
188|  override?: Partial<MusicConfig>,
189|): ScheduleDecision {
190|  const config = resolveConfig(override ?? MUSIC_CONFIG);
191|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
192|  const next = nextTrack(signal, manifest, state.currentId, config, env.selection);
193|  if (!next) return noChange(state);
194|  return {
195|    state: {
196|      ...state,
197|      currentId: next.id,
198|      currentStartedSec: nowSec,
199|      overrideId: next.id,
200|      overrideSceneId: state.activeSceneId,
201|    },
202|    switchToId: next.id,
203|    crossfadeSec: config.crossfadeSec,
204|    hardCut: false,
205|  };
206|}
207|
208|// Manual pick from Previous: the track holds like a Next until the next
209|// scene change. Unknown ids change nothing.
210|export function requestManualTrack(
211|  state: SchedulerState,
212|  manifest: MusicManifest,
213|  trackId: string,
214|  nowSec: number,
215|  override?: Partial<MusicConfig>,
216|): ScheduleDecision {
217|  const config = resolveConfig(override ?? MUSIC_CONFIG);
218|  if (state.playlist !== null) return noChange(state);
219|  const picked = manifest.tracks.find((t) => t.id === trackId) ?? null;
220|  if (!picked) return noChange(state);
221|  return {
222|    state: {
223|      ...state,
224|      currentId: picked.id,
225|      currentStartedSec: nowSec,
226|      overrideId: picked.id,
227|      overrideSceneId: state.activeSceneId,
228|    },
229|    switchToId: picked.id,
230|    crossfadeSec: config.crossfadeSec,
231|    hardCut: false,
232|  };
233|}
234|
235|// A non-looping track ended: fade into the best remaining track,
236|// excluding the one that just ended. Never crosses styles.
237|export function noteTrackEnded(
238|  state: SchedulerState,
239|  signal: SceneSignal | null,
240|  manifest: MusicManifest,
241|  endedId: string,
242|  nowSec: number,
243|  env: SelectEnv,
244|  override?: Partial<MusicConfig>,
245|): ScheduleDecision {
246|  const config = resolveConfig(override ?? MUSIC_CONFIG);
247|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
248|  const styleTracks = candidatesFor(env.selection, manifest).filter((t) => t.id !== endedId);
249|  if (styleTracks.length === 0) return noChange(state);
250|  const best = topRanked(signal, { ...manifest, tracks: styleTracks }, config);
251|  if (!best) return noChange(state);
252|  return {
253|    state: {
254|      ...state,
255|      currentId: best.id,
256|      currentStartedSec: nowSec,
257|      overrideId: null,
258|      overrideSceneId: null,
259|    },
260|    switchToId: best.id,
261|    crossfadeSec: config.crossfadeSec,
262|    hardCut: false,
263|  };
264|}
265|
266|// Fixed playlist mode (the Chopin easter egg). Playlist order lives here
267|// because it reuses SchedulerState and the crossfade config.
268|function playlistById(manifest: MusicManifest, id: string) {
269|  return manifest.playlists.find((p) => p.id === id) ?? null;
270|}
271|
272|// Enter playlist mode: switch at once to the first track, with no dwell
273|// and no min-track rule. Scene changes stay tracked but never switch.
274|export function enterPlaylist(
275|  state: SchedulerState,
276|  manifest: MusicManifest,
277|  playlistId: string,
278|  nowSec: number,
279|  override?: Partial<MusicConfig>,
280|): ScheduleDecision {
281|  const config = resolveConfig(override ?? MUSIC_CONFIG);
282|  const playlist = playlistById(manifest, playlistId);
283|  const firstId = playlist?.trackIds[0];
284|  const first = firstId ? (manifest.tracks.find((t) => t.id === firstId) ?? null) : null;
285|  if (!playlist || !first) return noChange(state);
286|  return {
287|    state: {
288|      ...state,
289|      currentId: first.id,
290|      currentStartedSec: nowSec,
291|      overrideId: null,
292|      overrideSceneId: null,
293|      playlist: { id: playlist.id, index: 0 },
294|    },
295|    switchToId: first.id,
296|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
297|    hardCut: false,
298|  };
299|}
300|
301|// Next playlist track in trackIds order, wrapping last to first. Used by
302|// both the end-of-track path and the Next button while the playlist is on.
303|function advancePlaylist(
304|  state: SchedulerState,
305|  manifest: MusicManifest,
306|  nowSec: number,
307|  config: MusicConfig,
308|): ScheduleDecision {
309|  if (state.playlist === null) return noChange(state);
310|  const playlist = playlistById(manifest, state.playlist.id);
311|  if (!playlist || playlist.trackIds.length === 0) return noChange(state);
312|  // A one-track playlist wraps onto the same id. That still returns a
313|  // switch so the ended element re-cues instead of going quiet.
314|  const nextIndex = (state.playlist.index + 1) % playlist.trackIds.length;
315|  const nextId = playlist.trackIds[nextIndex];
316|  if (nextId === undefined) return noChange(state);
317|  const next = manifest.tracks.find((t) => t.id === nextId) ?? null;
318|  if (!next) return noChange(state);
319|  return {
320|    state: {
321|      ...state,
322|      currentId: next.id,
323|      currentStartedSec: nowSec,
324|      overrideId: null,
325|      overrideSceneId: null,
326|      playlist: { id: playlist.id, index: nextIndex },
327|    },
328|    switchToId: next.id,
329|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
330|    hardCut: false,
331|  };
332|}
333|
334|// Leave playlist mode: clear the playlist state and switch at once to the
335|// best match for the current scene under the restored selection.
336|export function exitPlaylist(
337|  state: SchedulerState,
338|  signal: SceneSignal | null,
339|  manifest: MusicManifest,
340|  nowSec: number,
341|  env: SelectEnv,
342|  override?: Partial<MusicConfig>,
343|): ScheduleDecision {
344|  if (state.playlist === null) return noChange(state);
345|  const config = resolveConfig(override ?? MUSIC_CONFIG);
346|  const styleTracks = candidatesFor(env.selection, manifest);
347|  const cleared: SchedulerState = {
348|    ...state,
349|    overrideId: null,
