33|// 1280x800 fit: ~560 px of text area at the 19 px / 1.7 book line holds
34|// 17 lines; the 65ch column fits ~68 chars per line, so each paragraph
35|// costs ceil(chars / 68) lines and short dialogue lines each take a full
36|// line. Page one also carries the scene heading, so it budgets one less.
37|// Paragraphs stay whole; one over budget takes its own page.
38|export const PAGE_WORD_BUDGET = 250;
39|export const CHARS_PER_LINE = 68;
40|export const LINES_PER_PAGE = 17;
41|export const FIRST_PAGE_LINES = 16;
42|
43|export interface SubPage {
44|  paragraphs: ReaderParagraph[];
45|  startN: number;
46|  endN: number;
47|  words: number;
48|}
49|
50|export function countWords(text: string): number {
51|  const words = text.split(/\s+/).filter((w) => w.length > 0);
52|  return words.length;
53|}
54|
55|export function estimateLines(text: string): number {
56|  return Math.max(1, Math.ceil(text.length / CHARS_PER_LINE));
57|}
58|
59|// Split one scene into sub-pages at paragraph boundaries: a page closes
60|// when the next paragraph would pass the word budget or the line budget.
61|export function paginateScene(
62|  paragraphs: ReaderParagraph[],
63|  budgetWords: number = PAGE_WORD_BUDGET,
64|): SubPage[] {
65|  const pages: SubPage[] = [];
66|  let current: ReaderParagraph[] = [];
67|  let words = 0;
68|  let lines = 0;
69|  const flush = () => {
70|    if (current.length === 0) return;
71|    pages.push({
72|      paragraphs: current,
73|      startN: current[0]?.n ?? 0,
74|      endN: current[current.length - 1]?.n ?? 0,
75|      words,
76|    });
77|    current = [];
78|    words = 0;
79|    lines = 0;
80|  };
81|  for (const p of paragraphs) {
82|    const w = countWords(p.text);
83|    const l = estimateLines(p.text);
84|    const budget = pages.length === 0 ? FIRST_PAGE_LINES : LINES_PER_PAGE;
85|    if (current.length > 0 && (words + w > budgetWords || lines + l > budget)) flush();
86|    current.push(p);
87|    words += w;
88|    lines += l;
89|  }
90|  flush();
91|  if (pages.length === 0) pages.push({ paragraphs: [], startN: 0, endN: 0, words: 0 });
92|  return pages;
93|}
94|
95|export interface SceneView {
96|  sceneId: string;
97|  ch: number;
98|  chapterTitle: string;
99|  title: string;
100|  emotion: ReaderScene["emotion"];
101|  pages: SubPage[];
102|  prevSceneId: string | null;
103|  nextSceneId: string | null;
104|  k: number;
105|  n: number;
106|}
107|
108|// The only text a scene route ships: this scene, its chapter, its pages,
109|// and neighbor ids for the pager. Throws on unknown scene id.
110|export function buildSceneView(
111|  model: ReaderModel,
112|  sceneId: string,
113|  budgetWords: number = PAGE_WORD_BUDGET,
114|): SceneView {
115|  const flat = model.chapters.flatMap((c) => c.scenes.map((s) => ({ ch: c.ch, chapterTitle: c.title, scene: s })));
116|  const at = flat.findIndex((e) => e.scene.id === sceneId);
117|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
118|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
119|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
120|  const prev = at > 0 ? flat[at - 1] : null;
121|  const next = at < flat.length - 1 ? flat[at + 1] : null;
122|  return {
123|    sceneId,
124|    ch: entry.ch,
125|    chapterTitle: entry.chapterTitle,
126|    title: entry.scene.title,
127|    emotion: entry.scene.emotion,
128|    pages: paginateScene(entry.scene.paragraphs, budgetWords),
129|    prevSceneId: prev?.scene.id ?? null,
130|    nextSceneId: next?.scene.id ?? null,
131|    k: chapterScenes.findIndex((e) => e.scene.id === sceneId) + 1,
132|    n: chapterScenes.length,
133|  };
134|}
135|
136|export interface NavState {
137|  sceneId: string;
138|  page: number;
139|}
140|
141|export type NavAction =
142|  | { kind: "next" }
143|  | { kind: "prev" }
144|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
145|
146|export interface NavIndex {
147|  order: string[];
148|  pageCounts: Map<string, number>;
149|}
150|
151|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
152|  return {
153|    order: views.map((v) => v.sceneId),
154|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
155|  };
156|}
157|
158|// Every pager move in one place: next/prev cross scenes and chapters,
159|// going back lands on the last sub-page, bounds are no-ops, unknown
160|// goto ids keep state.
161|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
162|  const at = index.order.indexOf(state.sceneId);
163|  if (at < 0) return state;
164|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
165|  if (action.kind === "next") {
166|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
167|    const nextId = index.order[at + 1];
168|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
169|  }
170|  if (action.kind === "prev") {
171|    if (state.page > 0) return { ...state, page: state.page - 1 };
172|    const prevId = at > 0 ? index.order[at - 1] : undefined;
173|    if (prevId === undefined) return state;
174|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
175|  }
176|  if (index.order.indexOf(action.sceneId) < 0) return state;
177|  const count = index.pageCounts.get(action.sceneId) ?? 1;
178|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
179|}
180|
181|// True only when the scene id changed. The container gates observeScene
182|// on this, so sub-page moves never touch the scheduler.
183|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
184|  return prevSceneId !== nextSceneId;
185|}
186|
187|export interface SceneEntryGate {
188|  observedId: string | null;
189|  routeId: string | null;
190|  manifestReady: boolean;
191|}
192|
193|// The container's effect gate in one testable place: observe exactly once
194|// per route id, only after the manifest lands. Route params can lag a
195|// render, so the last observed id is compared before every observe call.
196|export function nextSceneEntry(gate: SceneEntryGate): {
197|  shouldObserve: boolean;
198|  nextObservedId: string | null;
199|} {
200|  if (!gate.routeId || !gate.manifestReady || !isSceneEntry(gate.observedId, gate.routeId)) {
201|    return { shouldObserve: false, nextObservedId: gate.observedId };
202|  }
203|  return { shouldObserve: true, nextObservedId: gate.routeId };
204|}
205|
206|// Throws on unordered scenes and on paragraphs covered zero or two times.
207|export function buildReaderModel(
208|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
209|  analysis: { scenes: AnalyzedScene[] },
210|): ReaderModel {
211|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
212|  const scenes = [...analysis.scenes];
213|  for (let i = 1; i < scenes.length; i++) {
214|    const prev = scenes[i - 1];
215|    const cur = scenes[i];
216|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
217|      throw new Error(`scenes out of order at ${cur.id}`);
218|    }
219|  }
220|  const seen = new Set<number>();
221|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
222|  for (const scene of scenes) {
223|    const paras: ReaderParagraph[] = [];
224|    for (let n = scene.start_n; n <= scene.end_n; n++) {
225|      const p = byN.get(n);
226|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
227|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
228|      seen.add(n);
229|      paras.push({ id: p.id, n: p.n, text: p.text });
230|    }
231|    sceneParagraphs.set(scene.id, paras);
232|  }
233|  if (seen.size !== book.paragraphs.length) {
234|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
235|  }
236|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
237|    const mine = scenes.filter((s) => s.ch === chapter.ch);
238|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
239|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
240|    }
241|    return {
242|      ch: chapter.ch,
243|      title: chapter.title,
244|      scenes: mine.map((s) => ({
245|        id: s.id,
246|        title: s.title,
247|        emotion: s.final === null ? null : { ...s.final },
248|        paragraphs: sceneParagraphs.get(s.id) ?? [],
249|      })),
250|    };
251|  });
252|  return {
253|    bookId: book.id,
254|    textVersion: book.textVersion,
255|    title: book.title,
256|    author: book.author,
257|    chapters,
258|  };
259|}

