1|// Session track selection. Pure: no env, no fetch, no audio.
2|import type {
3|  MusicConfig,
4|  MusicManifest,
5|  MusicSelection,
6|  PersistedMusicPrefs,
7|  Rng,
8|  SceneSignal,
9|  Track,
10|} from "./music-types";
11|import { dominantEmotion, rankTracks, resolveConfig } from "./music-similarity";
12|
13|// Style scope for every pick, minus playlist-only tracks. Playlist tracks
14|// never enter emotion selection, so the filter lives here, not in callers.
15|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
16|  const audible = manifest.tracks.filter((t) => t.playlistOnly !== true);
17|  if (selection.style === null) return audible;
18|  return audible.filter((t) => t.style === selection.style);
19|}
20|
21|// Next track: the next same-emotion track in score order across the whole
22|// style, wrapping and skipping the current. With no other same-emotion
23|// track, the best same-style track overall. A null scene cycles the style
24|// set in id order. One track or none gives null.
25|export function nextTrack(
26|  scene: SceneSignal | null,
27|  manifest: MusicManifest,
28|  currentTrackId: string | null,
29|  override?: Partial<MusicConfig>,
30|  selection?: MusicSelection | null,
31|): Track | null {
32|  const scope =
33|    selection == null
34|      ? manifest.tracks.filter((t) => t.playlistOnly !== true)
35|      : candidatesFor(selection, manifest);
36|  if (scope.length <= 1) return null;
37|  const config = resolveConfig(override);
38|  const scoped = { ...manifest, tracks: scope };
39|  if (scene === null) {
40|    const ids = [...scope].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
41|    const at = ids.findIndex((t) => t.id === currentTrackId);
42|    return ids[(at + 1) % ids.length] as Track;
43|  }
44|  const ranked = rankTracks(scene, scoped, config);
45|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
46|  const others = same.filter((t) => t.id !== currentTrackId);
47|  if (others.length > 0) {
48|    const at = same.findIndex((t) => t.id === currentTrackId);
49|    if (at >= 0) return same[(at + 1) % same.length] as Track;
50|    return same[0] as Track;
51|  }
52|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
53|}
54|
55|// Random mode draw: same-style tracks with the scene's dominant emotion
56|// (or the whole style set when none matches), scored, kept within
57|// randomTolerance of the best. The current track stays when eligible;
58|// otherwise the draw skips it when an alternative exists.
59|export function pickRandomTrack(
60|  cands: Track[],
61|  scene: SceneSignal | null,
62|  excludeId: string | null,
63|  rng: Rng,
64|  override?: Partial<MusicConfig>,
65|): Track | null {
66|  if (cands.length === 0) return null;
67|  if (scene === null) {
68|    const ids = [...cands].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
69|    const at = ids.findIndex((t) => t.id === excludeId);
70|    return ids[(at + 1) % ids.length] as Track;
71|  }
72|  const config = resolveConfig(override);
73|  const scoped = { version: 3, styles: [], soundtracks: [], playlists: [], tracks: cands };
74|  const ranked = rankTracks(scene, scoped, config);
75|  const dom = dominantEmotion(scene);
76|  const pool = ranked.filter((t) => t.emotion === dom);
77|  const kept = (pool.length > 0 ? pool : ranked).map((t) => ({
78|    track: t,
79|    score: config.similarity(scene, t, config.weights),
80|  }));
81|  const best = kept[0]?.score ?? 0;
82|  const eligible = kept.filter((e) => e.score >= best - config.randomTolerance);
83|  const current = excludeId !== null ? eligible.find((e) => e.track.id === excludeId) : undefined;
84|  if (current) return current.track;
85|  const rest = eligible.filter((e) => e.track.id !== excludeId);
86|  const drawFrom = rest.length > 0 ? rest : eligible;
87|  if (drawFrom.length === 0) return null;
88|  return (drawFrom[Math.floor(rng() * drawFrom.length)] as { track: Track }).track;
89|}
90|
91|// True when the style has at least one emotion-selectable track. The style
92|// selector uses this, so a style with only playlist tracks stays hidden.
93|export function styleHasTracks(manifest: MusicManifest, style: string): boolean {
94|  return manifest.tracks.some((t) => t.style === style && t.playlistOnly !== true);
95|}
96|
97|// Session defaults on load. A stored style with no tracks falls back to
98|// the first style that has any.
99|export function resolveInitialSelection(
100|  manifest: MusicManifest,
101|  persisted: PersistedMusicPrefs | null,
102|): MusicSelection {
103|  const fallback = manifest.styles.find((s) => styleHasTracks(manifest, s.id))?.id ?? null;
104|  const style =
105|    persisted?.style !== null &&
106|    persisted?.style !== undefined &&
107|    styleHasTracks(manifest, persisted.style)
108|      ? persisted.style
109|      : fallback;
110|  return { style };
111|}
112|
113|// Style change from user action: the best match for the scene in the new
114|// style by score. Never crosses styles. Null when the style has no tracks.
115|export function requestStyleChange(
116|  manifest: MusicManifest,
117|  style: string,
118|  scene: SceneSignal | null,
119|  override?: Partial<MusicConfig>,
120|): { track: Track } | null {
121|  const scoped = manifest.tracks.filter((t) => t.style === style && t.playlistOnly !== true);
122|  if (scoped.length === 0) return null;
123|  const config = resolveConfig(override);
124|  if (scene === null) {
125|    const first = [...scoped].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0] as Track;
126|    return { track: first };
127|  }
128|  const track = rankTracks(scene, { ...manifest, tracks: scoped }, config)[0] as Track;
129|  return { track };
