1|// Pure music scheduler. The reader calls it with explicit nowSec values,
2|// so dwell, hysteresis, and hard cuts are testable without timers.
3|import {
4|  MUSIC_CONFIG,
5|  candidatesFor,
6|  nextTrack,
7|  pickRandomTrack,
8|  requestStyleChange,
9|  rankTracks,
10|  resolveConfig,
11|  scoreTrack,
12|} from "./music";
13|import type { MusicConfig, MusicManifest, SceneSignal, SelectEnv, Track } from "./music";
14|
15|export interface SchedulerState {
16|  currentId: string | null;
17|  currentStartedSec: number;
18|  activeSceneId: string | null;
19|  pendingSceneId: string | null;
20|  pendingSinceSec: number;
21|  overrideId: string | null;
22|  overrideSceneId: string | null;
23|  playlist: { id: string; index: number } | null;
24|}
25|
26|export interface ScheduleDecision {
27|  state: SchedulerState;
28|  switchToId: string | null;
29|  crossfadeSec: number;
30|  hardCut: boolean;
31|}
32|
33|export function initScheduler(): SchedulerState {
34|  return {
35|    currentId: null,
36|    currentStartedSec: 0,
37|    activeSceneId: null,
38|    pendingSceneId: null,
39|    pendingSinceSec: 0,
40|    overrideId: null,
41|    overrideSceneId: null,
42|    playlist: null,
43|  };
44|}
45|
46|function noChange(state: SchedulerState): ScheduleDecision {
47|  return { state, switchToId: null, crossfadeSec: 0, hardCut: false };
48|}
49|
50|function topRanked(
51|  signal: SceneSignal | null,
52|  manifest: MusicManifest,
53|  config: MusicConfig,
54|  excludeId?: string | null,
55|): { id: string; score: number } | null {
56|  if (signal === null) {
57|    const ids = [...manifest.tracks]
58|      .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
59|      .filter((t) => t.id !== excludeId);
60|    const first = ids[0];
61|    return first ? { id: first.id, score: 0 } : null;
62|  }
63|  const ranked = rankTracks(signal, manifest, config).filter((t) => t.id !== excludeId);
64|  const best = ranked[0];
65|  return best ? { id: best.id, score: scoreTrack(signal, best, config) } : null;
66|}
67|
68|// Scheduled select: the draw keeps the current
69|// track when it is eligible, so rescans do not churn. Dwell is handled
70|// by promotion; min-track holds the current pick.
71|function evaluateRandom(
72|  state: SchedulerState,
73|  signal: SceneSignal,
74|  styleTracks: Track[],
75|  scoped: MusicManifest,
76|  nowSec: number,
77|  config: MusicConfig,
78|  env: SelectEnv,
79|): ScheduleDecision {
80|  const pick = pickRandomTrack(styleTracks, signal, state.currentId, env.rng, config);
81|  if (!pick || pick.id === state.currentId) return noChange(state);
82|  if (state.currentId !== null && nowSec - state.currentStartedSec < config.minTrackSec) {
83|    return noChange(state);
84|  }
85|  return {
86|    state: { ...state, currentId: pick.id, currentStartedSec: nowSec },
87|    switchToId: pick.id,
88|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
89|    hardCut: false,
90|  };
91|}
92|
93|function evaluateSwitch(
94|  state: SchedulerState,
95|  signal: SceneSignal | null,
96|  manifest: MusicManifest,
97|  nowSec: number,
98|  config: MusicConfig,
99|  env: SelectEnv,
100|): ScheduleDecision {
101|  if (signal === null) return noChange(state);
102|  if (state.playlist !== null) return noChange(state);
103|  const styleTracks = candidatesFor(env.selection, manifest);
104|  if (styleTracks.length === 0) return noChange(state);
105|  const scoped = { ...manifest, tracks: styleTracks };
106|  return evaluateRandom(state, signal, styleTracks, scoped, nowSec, config, env);
107|}
108|
109|function promote(
110|  state: SchedulerState,
111|  sceneId: string,
112|  signal: SceneSignal | null,
113|  manifest: MusicManifest,
114|  nowSec: number,
115|  config: MusicConfig,
116|  env: SelectEnv,
117|): ScheduleDecision {
118|  const settled: SchedulerState = {
119|    ...state,
120|    activeSceneId: sceneId,
121|    pendingSceneId: null,
122|    pendingSinceSec: 0,
123|    overrideId: null,
124|    overrideSceneId: null,
125|  };
126|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
127|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
128|}
129|
130|// The reading position entered a scene. It becomes pending and the dwell
131|// clock restarts, so fast scrolling keeps only the newest scene. After
132|// the pending scene holds for dwellSec it becomes active. The first
133|// track ever plays at once, with no dwell.
134|export function observeScene(
135|  state: SchedulerState,
136|  sceneId: string,
137|  signal: SceneSignal | null,
138|  manifest: MusicManifest,
139|  nowSec: number,
140|  env: SelectEnv,
141|  override?: Partial<MusicConfig>,
142|): ScheduleDecision {
143|  const config = resolveConfig(override ?? MUSIC_CONFIG);
144|  if (state.currentId === null) {
145|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
146|  }
147|  if (sceneId === state.activeSceneId) {
148|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
149|  }
150|  if (sceneId !== state.pendingSceneId) {
151|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
152|  }
153|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
154|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
155|}
