158|// Every pager move in one place: next/prev cross scenes and chapters,
159|// going back lands on the last sub-page, bounds are no-ops, unknown
160|// goto ids keep state.
161|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
162|  const at = index.order.indexOf(state.sceneId);
163|  if (at < 0) return state;
164|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
165|  if (action.kind === "next") {
166|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
167|    const nextId = index.order[at + 1];
168|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
169|  }
170|  if (action.kind === "prev") {
171|    if (state.page > 0) return { ...state, page: state.page - 1 };
172|    const prevId = at > 0 ? index.order[at - 1] : undefined;
173|    if (prevId === undefined) return state;
174|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
175|  }
176|  if (index.order.indexOf(action.sceneId) < 0) return state;
177|  const count = index.pageCounts.get(action.sceneId) ?? 1;
178|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
