189|// In-memory KV for tests. Expiries are checked against Date.now.
190|export function createMemoryKV(): KV & { clear(): void } {
191|  const values = new Map<string, string>();
192|  const expiresAt = new Map<string, number>();
193|  function live(key: string): boolean {
194|    const until = expiresAt.get(key);
195|    if (until !== undefined && Date.now() >= until) {
196|      values.delete(key);
197|      expiresAt.delete(key);
198|      return false;
199|    }
200|    return true;
201|  }
202|  function num(key: string): number {
203|    return Number(values.get(key) ?? "0");
204|  }
205|  return {
