207|      if (!live(key)) return null;
208|      return values.get(key) ?? null;
209|    },
210|    async setNxEx(key: string, value: string, exSec: number): Promise<boolean> {
211|      if (live(key) && values.has(key)) return false;
212|      values.set(key, value);
213|      expiresAt.set(key, Date.now() + exSec * 1000);
214|      return true;
215|    },
216|    async set(key: string, value: string): Promise<void> {
217|      values.set(key, value);
218|      expiresAt.delete(key);
219|    },
220|    async incr(key: string): Promise<number> {
221|      const next = num(key) + 1;
222|      values.set(key, String(next));
223|      return next;
224|    },
225|    async incrBy(key: string, by: number): Promise<number> {
226|      const next = num(key) + by;
227|      values.set(key, String(next));
228|      return next;
229|    },
230|    async decr(key: string): Promise<number> {
231|      const next = num(key) - 1;
232|      values.set(key, String(next));
233|      return next;
234|    },
235|    async decrBy(key: string, by: number): Promise<number> {
236|      const next = num(key) - by;
237|      values.set(key, String(next));
238|      return next;
239|    },
240|    async expire(key: string, sec: number): Promise<void> {
241|      if (values.has(key)) expiresAt.set(key, Date.now() + sec * 1000);
242|    },
243|    async releaseIfToken(key: string, token: string): Promise<boolean> {
244|      if (!live(key)) return false;
245|      if (values.get(key) !== token) return false;
246|      values.delete(key);
247|      expiresAt.delete(key);
248|      return true;
249|    },
250|    clear(): void {
251|      values.clear();
252|      expiresAt.clear();
253|    },
254|  };
