217|      values.set(key, value);
218|      expiresAt.delete(key);
219|    },
220|    async incr(key: string): Promise<number> {
221|      const next = num(key) + 1;
222|      values.set(key, String(next));
223|      return next;
224|    },
225|    async incrBy(key: string, by: number): Promise<number> {
226|      const next = num(key) + by;
227|      values.set(key, String(next));
228|      return next;
229|    },
230|    async decr(key: string): Promise<number> {
231|      const next = num(key) - 1;
232|      values.set(key, String(next));
233|      return next;
234|    },
235|    async decrBy(key: string, by: number): Promise<number> {
236|      const next = num(key) - by;
237|      values.set(key, String(next));
238|      return next;
239|    },
