6|import type { NavAction, SceneView } from "@/core/reader";
7|import { PictureSlot, usePictureScene } from "../picture-panel";
8|
9|export interface ChapterJump {
10|  ch: number;
11|  title: string;
12|  firstSceneId: string;
13|}
14|
15|// One-shot entry intent: set just before pushing the previous scene
16|// route, so the new page opens on its last sub-page. Client memory only,
17|// never the URL, so prerendered pages stay static and a direct URL load
18|// always starts at page 0.
19|let enterAtEnd = false;
20|
21|// Set on every in-app scene push. The heading takes focus only when this
22|// is set, so first load shows no focus ring.
23|let hasNavigated = false;
24|
25|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
26|// Sub-page moves stay in client state; scene moves push a new route.
27|export function ScenePage({
28|  view,
29|  chapters,
30|  views,
31|  bookId,
32|  textVersion,
33|}: {
34|  view: SceneView;
35|  chapters: ChapterJump[];
36|  views: { sceneId: string; pages: number }[];
37|  bookId: string;
38|  textVersion: string;
39|}) {
40|  const pic = usePictureScene({ bookId, textVersion, sceneId: view.sceneId });
41|  const router = useRouter();
42|  const index = useMemo(() => buildNavIndex(views), [views]);
43|  const lastPage = view.pages.length - 1;
44|  const [page, setPage] = useState(() => {
45|    if (enterAtEnd) {
46|      enterAtEnd = false;
47|      return lastPage;
48|    }
49|    return 0;
50|  });
51|  const headingRef = useRef<HTMLHeadingElement>(null);
52|  const sub = view.pages[page] ?? view.pages[0];
53|  const atStart = view.prevSceneId === null && page === 0;
54|  const atBookEnd = view.nextSceneId === null && page === lastPage;
55|
56|  // Every pager move runs through navReducer; a new scene id means a
57|  // route push, a same-scene result means a client sub-page move.
58|  function move(action: NavAction) {
59|    pic.hidePopover();
60|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
61|    if (next.sceneId !== view.sceneId) {
62|      hasNavigated = true;
63|      if (next.page > 0) enterAtEnd = true;
64|      router.push(`/leer/${next.sceneId}`);
65|      return;
66|    }
67|    if (next.page !== page) {
68|      setPage(next.page);
69|      window.scrollTo(0, 0);
70|    }
71|  }
72|
73|  function goNext() {
74|    move({ kind: "next" });
75|  }
76|
77|  function goPrev() {
78|    move({ kind: "prev" });
79|  }
80|
81|  // Scene entry resets orientation; sub-page moves keep the heading.
82|  useEffect(() => {
83|    if (hasNavigated) headingRef.current?.focus();
84|    window.scrollTo(0, 0);
85|  }, [view.sceneId]);
